-- ========================================
-- PL MASS — carga inicial de mara_mass (correr DESPUÉS de
-- mara-mass.sql, en el SQL Editor de WMS Dashboard).
-- Generado desde la hoja "MARA" de la plantilla
-- Plantilla_Carga_LPN_Supermercados_2026_V.7 ... .xlsm
-- (espacios duros/dobles limpiados, #N/A -> null). Si un SKU ya
-- existe, no se pisa.
-- ========================================

on conflict (sku) do nothing;

-- Unidades siempre en mayúscula (la MARA trae algunas "pck"/"cja"/"und").
update public.mara_mass set unidad_venta = upper(unidad_venta), unidad_base = upper(unidad_base);
